```js
#!/usr/bin/env node
import Anthropic from '@anthropic-ai/sdk';
const client = new Anthropic(); // reads ANTHROPIC_API_KEY from env

const diff = process.argv[2];
if (!diff) {
  console.error('Usage: node pr-describe.mjs "<git diff>"');
  process.exit(1);
}

const res = await client.messages.create({
  model: 'claude-3-haiku-20240307',
  max_tokens: 300,
  system: 'You write clear pull request descriptions. Given a git diff, output: one line title, blank line, then 3-5 bullet points. Be concise and technical.',
  messages: [{ role: 'user', content: diff }]
});

console.log(res.content[0].text);
```

Save as `pr-describe.mjs`. Set `ANTHROPIC_API_KEY` in your shell. Run:
```bash
export ANTHROPIC_API_KEY=sk-ant-...
node pr-describe.mjs "$(git diff main)"
```

### minimist: the simplest arg parser

```bash
npm install minimist
```

```js
import minimist from 'minimist';
const args = minimist(process.argv.slice(2), {
  string: ['model', 'format'],
  boolean: ['verbose', 'json'],
  default: { model: 'haiku', format: 'text', verbose: false },
  alias: { v: 'verbose', m: 'model' }
});
// node tool.mjs input.txt -m sonnet --json
// args._      = ['input.txt']
// args.model  = 'sonnet'
// args.json   = true
```

### Two flags worth adding to every tool

**Model selection:**
```js
const MODEL_MAP = {
  haiku: 'claude-3-haiku-20240307',
  sonnet: 'claude-sonnet-4-6',
};
const model = MODEL_MAP[args.model] ?? MODEL_MAP.haiku;
// Default cheap, upgrade when needed: -m sonnet
```

**JSON output (for piping):**
```js
if (args.json) {
  console.log(JSON.stringify({ result: res.content[0].text }));
} else {
  console.log(res.content[0].text);
}
// node tool.mjs input.txt --json | jq '.result'
```

```js
// 1. Validate inputs first
if (!args._.length) {
  console.error('Error: No input provided.');
  console.error('Usage: node tool.mjs <file> [--model sonnet] [--json]');
  process.exit(1); // exit 1 = error (scripts can detect this)
}

// 2. Wrap API call
try {
  const res = await client.messages.create(...);
  console.log(res.content[0].text);
} catch (err) {
  if (err.status === 429) console.error('Rate limited — wait a moment and retry.');
  else if (err.status === 401) console.error('Bad API key. Check ANTHROPIC_API_KEY.');
  else if (err.status === 400) console.error('Bad request:', err.message);
  else console.error('Unexpected error:', err.message);
  process.exit(1);
}
```

Good error messages tell users exactly what went wrong and how to fix it.

### Two additions to make it a real CLI

**1. `bin` in package.json:**
```json
{
  "name": "pr-describe",
  "version": "1.0.0",
  "type": "module",
  "bin": { "pr-describe": "./index.mjs" }
}
```

**2. Shebang at top of script:**
```js
#!/usr/bin/env node
import Anthropic from '@anthropic-ai/sdk';
// ...
```

`bin` = command name → file mapping. Shebang = OS knows to run with Node. That's the entire recipe.

```js
const apiKey = process.env.ANTHROPIC_API_KEY;
if (!apiKey) {
  console.error('Error: ANTHROPIC_API_KEY is not set.');
  console.error('1. Get your key: https://console.anthropic.com/');
  console.error('2. Set it: export ANTHROPIC_API_KEY=sk-ant-...');
  console.error('   (Add to ~/.zshrc or ~/.bashrc to persist)');
  process.exit(1);
}
const client = new Anthropic({ apiKey });
```

### README structure that works:
1. What it does (1 sentence + example)
2. `npx your-tool` install/run
3. Setup: export API key
4. Copy-pasteable examples
5. All flags documented in a table

```js
import { readFile, writeFile } from 'fs/promises';
import { readdirSync } from 'fs';

// Read file from arg
const input = args._[0] ? await readFile(args._[0], 'utf-8') : null;
if (!input) { console.error('Provide a file path'); process.exit(1); }

// Process
const res = await client.messages.create({ /* ... */ });

// Write or print
if (args.output) {
  await writeFile(args.output, res.content[0].text, 'utf-8');
  console.error(`Saved to ${args.output}`); // stderr keeps stdout clean for piping
} else {
  process.stdout.write(res.content[0].text);
}
```

Output of call 1 becomes input of call 2:

```js
// Step 1: Extract key points
const step1 = await client.messages.create({
  model: 'claude-3-haiku-20240307', max_tokens: 200,
  system: 'Extract 5 key points from this document. One per line.',
  messages: [{ role: 'user', content: document }]
});

// Step 2: Generate quiz questions from key points
const step2 = await client.messages.create({
  model: 'claude-3-haiku-20240307', max_tokens: 400,
  system: 'Generate 5 quiz questions from these key points.',
  messages: [{ role: 'user', content: step1.content[0].text }]
});

if (args.verbose) console.error('Key points:', step1.content[0].text);
console.log(step2.content[0].text);
```

This is the foundation of agentic multi-step tools.

```js
const files = readdirSync('./docs').filter(f => f.endsWith('.md'));
console.error(`Processing ${files.length} files...`);

const results = [];
for (let i = 0; i < files.length; i += 5) {
  const batch = files.slice(i, i + 5);
  const batchResults = await Promise.all(batch.map(async (file) => {
    const content = await readFile(`./docs/${file}`, 'utf-8');
    const res = await client.messages.create({
      model: 'claude-3-haiku-20240307', max_tokens: 150,
      system: 'Summarize in 2 sentences.',
      messages: [{ role: 'user', content }]
    });
    return { file, summary: res.content[0].text };
  }));
  results.push(...batchResults);
  if (i + 5 < files.length) await new Promise(r => setTimeout(r, 1000));
  console.error(`${Math.min(i + 5, files.length)}/${files.length} done`);
}

await writeFile('summaries.json', JSON.stringify(results, null, 2));
console.error('Done.');
```

### The problem with hardcoded values

Anything that might change between users, machines, or runs shouldn't live inside your logic. That includes: API keys, default model, output format, file paths, rate limit settings.

### A minimal config file
```js
// config.json
{
  "model": "claude-3-haiku-20240307",
  "maxTokens": 300,
  "outputDir": "./output"
}
```

```js
import { readFileSync } from 'fs';
import { homedir } from 'os';
import { join } from 'path';

function loadConfig() {
  const defaults = { model: 'claude-3-haiku-20240307', maxTokens: 300, outputDir: './output' };
  const configPath = join(homedir(), '.pr-describe', 'config.json');
  try {
    const userConfig = JSON.parse(readFileSync(configPath, 'utf-8'));
    return { ...defaults, ...userConfig };
  } catch {
    return defaults; // no config file yet — use defaults
  }
}
```

Flags still override config, config still overrides defaults. That order matters: `flags > config file > defaults`.

The practical test: try to describe what the tool does in one sentence. "Fetches a URL" is one job with many dials (curl). "Imports invoice data, checks what's overdue, marks invoices paid, tracks clients, and exports reports" is five jobs wearing a trenchcoat. Once you're reaching for "and" more than once to describe your tool, subcommands are usually the right shape — not because it's more standard, but because each job gets to own its own arguments, its own validation, and its own help text without stepping on the others'.

Setting it up with Commander.js, the most common Node.js CLI framework, looks like this:

```js
#!/usr/bin/env node
import { Command } from 'commander';
const program = new Command();

program
  .name('invtrack')
  .description('Track overdue invoices from a CSV export')
  .version('1.0.0');

program
  .command('import <file>')
  .description('Import invoices from a CSV file')
  .action((file) => { /* ... */ });

program
  .command('overdue')
  .description('List invoices past their due date')
  .action(() => { /* ... */ });

program
  .command('pay <invoiceId>')
  .description('Mark an invoice as paid')
  .action((invoiceId) => { /* ... */ });

program.parse();
```

Each subcommand is its own small function with its own arguments. Nothing about `pay` needs to know `import` exists.

A default doesn't remove the flag — it just means the flag only has to be typed when the answer isn't the usual one. Commander.js makes this a one-line change:

```js
import { homedir } from 'os';
import { join } from 'path';

const DEFAULT_FILE = join(homedir(), '.invtrack', 'invoices.csv');

program
  .command('overdue')
  .option('-f, --file <path>', 'CSV file to read', DEFAULT_FILE)
  .action((options) => {
    // options.file is DEFAULT_FILE unless the user passed --file
  });
```

The rule of thumb: if you can name the value 90% of your users will pass without thinking about it, that value belongs as the default, not as a required flag. `git commit` doesn't require `--branch` because it defaults to the current one. `npm install` doesn't require `--registry` because it defaults to npm's. invtrack shouldn't require `--file` because almost everyone keeps their data in the same place.

Commander.js does this automatically if you call `program.parse()` and no subcommand matched — but it's worth confirming explicitly rather than assuming:

```js
program.parse();

if (!process.argv.slice(2).length) {
  program.outputHelp();
  process.exit(1);
}
```

The exit code matters as much as the message: exit `0` tells any script checking `$?` that the run succeeded. A bare invocation that printed nothing and did nothing wasn't a success, and it shouldn't claim to be one — this becomes important again in the errors-and-exit-codes module, where exit codes stop being a courtesy and start being an interface other programs depend on.

The fix is checking whether stdout is actually connected to a terminal before emitting any formatting, using Node's built-in `process.stdout.isTTY`:

```js
import chalk from 'chalk';

const useColor = process.stdout.isTTY;
const red = (s) => (useColor ? chalk.red(s) : s);
const yellow = (s) => (useColor ? chalk.yellow(s) : s);

for (const inv of overdueInvoices) {
  const line = inv.daysOverdue > 30 ? red(inv.summary) : yellow(inv.summary);
  console.log(line);
}
```

`isTTY` is `true` when a human is watching in a real terminal and `undefined` (falsy) the moment output is redirected or piped — most modern CLI color libraries, including chalk, actually do this detection for you automatically. Knowing the mechanism still matters: it's the same `isTTY` check you'll reach for deciding whether to show a progress spinner, a percentage bar, or an interactive prompt at all, which is where the last lesson of this module picks back up.

